.catalog-sidebar {
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.catalog-sidebar h2 {
    margin: 0 0 0.5rem;
    font-size: 1.25rem;
}

.filter-section {
    margin-bottom: 1rem;
}

.filter-section h3 {
    font-size: 0.95rem;
    margin: 0 0 0.5rem;
    color: #495057;
}

.filter-hint {
    font-size: 0.85rem;
    color: #6c757d;
    margin: 0;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.25rem 0;
    cursor: pointer;
    font-size: 0.9rem;
}

.price-inputs {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
    color: #495057;
}

.price-inputs input {
    padding: 0.4rem 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.9rem;
    margin-top: 0.2rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.btn-apply {
    padding: 0.5rem 1rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
}

.btn-apply:hover {
    background: #0b5ed7;
}

.btn-clear {
    padding: 0.5rem 1rem;
    background: transparent;
    color: #6c757d;
    border: 1px solid #ced4da;
    border-radius: 6px;
    cursor: pointer;
}

.btn-clear:hover {
    background: #e9ecef;
}

